<?php

namespace App\Services;

use App\Agent\Dto\OperationRequest;
use App\Contracts\AgentClient;
use App\Enums\AuditAction;
use App\Enums\AuditOutcome;
use App\Enums\DatabaseEngine;
use App\Enums\RequestState;
use App\Models\Application;
use App\Models\DatabaseRequest;
use App\Models\Task;
use App\Models\User;
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;

/**
 * App-scoped database intent only. The engine is a catalog ID, the credentials are
 * generated by the panel (never an arbitrary admin password), and provisioning is
 * a task. The panel's own SQLite database is never used for a hosted application.
 */
final class DatabaseService
{
    public function __construct(
        private readonly TaskService $tasks,
        private readonly AuditRecorder $audit,
        private readonly AgentClient $agent,
    ) {}

    public function request(User $actor, Application $application, string $engine, string $name, string $username, string $idempotencyKey): DatabaseRequest
    {
        if (! in_array($engine, config('hostnur.server.database_engines', []), true)) {
            throw ValidationException::withMessages(['engine' => 'Select a supported database engine.']);
        }

        $validated = validator([
            'database_name' => $name,
            'username' => $username,
        ], [
            'database_name' => ['required', 'string', 'regex:/^[a-z][a-z0-9_]{0,63}$/'],
            'username' => ['required', 'string', 'regex:/^[a-z][a-z0-9_]{0,63}$/'],
        ])->validate();

        $request = DatabaseRequest::create([
            'application_id' => $application->getKey(),
            'engine' => DatabaseEngine::from($engine),
            'database_name' => $validated['database_name'],
            'username' => $validated['username'],
            'password' => Str::password(32, symbols: false),
            'state' => RequestState::Requested,
        ]);

        $this->registerWithAgent($application, $request);

        $task = $this->tasks->requestApproved($actor, new OperationRequest(
            protocolVersion: (int) config('hostnur.protocol_version', 1),
            requestId: (string) Str::uuid(),
            idempotencyKey: $idempotencyKey,
            operation: 'database.provision',
            resource: null,
            parameters: ['request' => $request->getKey()],
            timeoutSeconds: null,
        ));

        $request->forceFill(['task_id' => $task->getKey()])->save();

        $this->audit->record($actor, AuditAction::DatabaseRequested, AuditOutcome::Requested, [
            'resource_kind' => 'application',
            'resource_id' => $application->getKey(),
            'metadata' => ['operation' => 'database.provision'],
        ]);

        return $request;
    }

    public function syncState(DatabaseRequest $request): DatabaseRequest
    {
        if ($request->task !== null) {
            $request->forceFill(['state' => RequestState::fromTaskStatus($request->task->status)])->save();
        }

        return $request;
    }

    /**
     * Remove a managed database (explicit destructive operation). Only acts on a
     * provisioned database; the agent drops only its registered DB/principal.
     */
    public function delete(User $actor, DatabaseRequest $request): void
    {
        if (config('hostnur.agent_mode') === 'real' && $request->state === RequestState::Succeeded) {
            try {
                $this->agent->removeDatabase(new OperationRequest(
                    protocolVersion: (int) config('hostnur.protocol_version', 1),
                    requestId: (string) Str::uuid(),
                    idempotencyKey: (string) Str::uuid(),
                    operation: 'agent.remove_database',
                    resource: null,
                    parameters: ['database' => $request->getKey()],
                    timeoutSeconds: null,
                ));
            } catch (\Throwable $exception) {
                throw ValidationException::withMessages([
                    'database' => 'Could not remove the database: '.$exception->getMessage(),
                ]);
            }
        }

        $applicationId = $request->application_id;
        $request->delete();

        $this->audit->record($actor, AuditAction::DatabaseRemoved, AuditOutcome::Success, [
            'resource_kind' => 'application',
            'resource_id' => $applicationId,
            'metadata' => ['operation' => 'database.remove'],
        ]);
    }

    /**
     * Rotate the managed database credential. The running application keeps the
     * previous credential in its release env until the next deployment, so a
     * redeploy is required to adopt the new one.
     */
    public function rotate(User $actor, DatabaseRequest $request): void
    {
        if (config('hostnur.agent_mode') !== 'real' || $request->state !== RequestState::Succeeded) {
            return;
        }

        try {
            $this->agent->rotateDatabase(new OperationRequest(
                protocolVersion: (int) config('hostnur.protocol_version', 1),
                requestId: (string) Str::uuid(),
                idempotencyKey: (string) Str::uuid(),
                operation: 'database.rotate',
                resource: null,
                parameters: ['database' => $request->getKey()],
                timeoutSeconds: null,
            ));
        } catch (\Throwable $exception) {
            throw ValidationException::withMessages([
                'database' => 'Could not rotate the credential: '.$exception->getMessage(),
            ]);
        }

        $this->audit->record($actor, AuditAction::DatabaseRequested, AuditOutcome::Requested, [
            'resource_kind' => 'application',
            'resource_id' => $request->application_id,
            'metadata' => ['operation' => 'database.rotate'],
        ]);
    }

    /**
     * Register the database allocation with the agent and adopt its derived
     * identifiers (the agent owns the naming and the credential).
     */
    private function registerWithAgent(Application $application, DatabaseRequest $request): void
    {
        if (config('hostnur.agent_mode') !== 'real') {
            return;
        }

        try {
            $response = $this->agent->registerDatabase(new OperationRequest(
                protocolVersion: (int) config('hostnur.protocol_version', 1),
                requestId: (string) Str::uuid(),
                idempotencyKey: (string) Str::uuid(),
                operation: 'agent.register_database',
                resource: null,
                parameters: [
                    'database' => $request->getKey(),
                    'application' => $application->getKey(),
                ],
                timeoutSeconds: null,
            ));
        } catch (\Throwable $exception) {
            throw ValidationException::withMessages([
                'database_name' => 'Could not register the database with the agent: '.$exception->getMessage(),
            ]);
        }

        if (isset($response['database'], $response['username'])) {
            $request->forceFill([
                'database_name' => $response['database'],
                'username' => $response['username'],
            ])->save();
        }
    }
}
